async function hover(setId,from,to){const s=await get(setId);for(const c of s.children){if(!c.name.includes(from))continue;const t=s.children.find(x=>x.name===c.name.replace(from,to));if(!t)continue;await c.setReactionsAsync([...c.reactions,{trigger:{type:'ON_HOVER'},actions:[act(t.id)]}]);n++;}}
